<?php/** * გვერდის რედაქტორი v3.4 (With Email Notifications) * + Slug Input Expanded * + Modular Editor * + Admin Email Alerts */global $ok_db;// 🛑 0. დამხმარე ფუნქციებიif (!function_exists('ok_get_base_url')) {    function ok_get_base_url() {        $protocol = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] === 'on') ? "https" : "http";        return $protocol . '://' . $_SERVER['HTTP_HOST'] . rtrim(dirname(dirname($_SERVER['SCRIPT_NAME'])), '/\\');    }}function ok_get_theme_templates() {    $theme = get_ok_option('active_theme', 'default');    $theme = preg_replace('/[^a-zA-Z0-9_-]/', '', $theme);    $path = $_SERVER['DOCUMENT_ROOT'] . '/ok-content/themes/' . $theme . '/';    $path = str_replace(['\\', '//'], '/', $path);    $templates = [];    if (is_dir($path)) {        $files = glob($path . '*.php');        if ($files) {            foreach ($files as $file) {                if (preg_match('/Template\s+Name\s*:\s*(.+)/mi', file_get_contents($file, false, null, 0, 8192), $matches)) {                    $templates[basename($file)] = trim($matches[1]);                }            }        }    }    return ['data' => $templates];}// ─────────────────────────────────────────────────────────────────────────────// AJAX SLUG HANDLER// ─────────────────────────────────────────────────────────────────────────────if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['ajax_action']) && $_POST['ajax_action'] === 'update_slug') {    if (!isset($_SESSION['user_id'])) { echo json_encode(['error' => 'Auth required']); exit; }        $post_id = (int)$_POST['post_id'];    $raw_slug = strip_tags(trim($_POST['slug']));    $title_fallback = strip_tags(trim($_POST['title']));    $source = !empty($raw_slug) ? $raw_slug : $title_fallback;        if (function_exists('generate_slug')) {        $slug = generate_slug($source);        $check_sql = "SELECT id FROM ok_posts WHERE post_name = ? AND id != ?";        if ($ok_db->get_var($check_sql, [$slug, $post_id])) {            $slug .= '-' . time();        }    } else {        $slug = strtolower(trim(preg_replace('/[^A-Za-z0-9-]+/', '-', $source)));    }    if ($post_id > 0) {        $ok_db->query("UPDATE ok_posts SET post_name = ? WHERE id = ?", [$slug, $post_id]);    }    header('Content-Type: application/json');    echo json_encode(['success' => true, 'new_slug' => $slug]);    exit;}// მენიუში დამატებაadd_ok_action('admin_menu', function() {    add_submenu_page('ok-pages', 'ახალი გვერდი', 'ახალი გვერდი', 'edit_pages', 'ok-page-editor', 'ok_render_page_editor');});// ─────────────────────────────────────────────────────────────────────────────// რენდერი (მთავარი ფუნქცია)// ─────────────────────────────────────────────────────────────────────────────function ok_render_page_editor() {    global $ok_db;    echo '<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>';    $post_id = isset($_GET['id']) ? (int)$_GET['id'] : 0;    $is_edit = ($post_id > 0);    $post    = null;    if ($is_edit) {        $post = $ok_db->get_row("SELECT * FROM ok_posts WHERE id = ?", [$post_id]);        if (!$post) { echo '<div class="alert alert-danger m-4">გვერდი არ მოიძებნა.</div>'; return; }    }    // --- SAVE LOGIC ---    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['save_page'])) {                if(function_exists('check_admin_referer') && !check_admin_referer('save_page_action')) {             die('Security Check Failed');        }        $title   = strip_tags(trim($_POST['post_title']));        $content = $_POST['post_content'];         $status  = in_array($_POST['post_status'], ['published', 'draft']) ? $_POST['post_status'] : 'draft';        $author  = isset($_SESSION['user_id']) ? (int)$_SESSION['user_id'] : 1;         $date    = date('Y-m-d H:i:s');        $has_sidebar = isset($_POST['has_sidebar']) ? 1 : 0;                $new_template = isset($_POST['page_template']) ? preg_replace('/[^a-zA-Z0-9_.-]/', '', $_POST['page_template']) : 'default';        $manual_slug = strip_tags(trim($_POST['post_name'] ?? ''));        $slug_source = !empty($manual_slug) ? $manual_slug : $title;                if (function_exists('generate_slug')) {            $slug = generate_slug($slug_source);            $check_sql = $is_edit ? "SELECT id FROM ok_posts WHERE post_name = ? AND id != ?" : "SELECT id FROM ok_posts WHERE post_name = ?";            $params = $is_edit ? [$slug, $post_id] : [$slug];            if ($ok_db->get_var($check_sql, $params)) { $slug .= '-' . time(); }        } else {            $slug = strtolower(trim(preg_replace('/[^A-Za-z0-9-]+/', '-', $slug_source)));            if (empty($slug)) $slug = 'page-' . time();        }                $image_url = filter_var($_POST['post_image_url'] ?? '', FILTER_SANITIZE_URL);        $feat_img_id = (int)($_POST['post_image_id'] ?? 0);        $content_img_ids = array_filter(explode(',', $_POST['content_image_ids'] ?? ''), 'is_numeric');        // NOTIFICATIONS MESSAGE BUILDER        $notif_message = "";        $u_row = $ok_db->get_row("SELECT username, display_name FROM ok_users WHERE id = ?", [$author]);        $user_label = ($u_row) ? $u_row->display_name : "User ID:".$author;        if (!$is_edit) {            $notif_message = "{$user_label}-მ დაამატა ახალი გვერდი: '{$title}'";        } else {            $changes = [];            if ($post->post_title !== $title) $changes[] = "შეცვალა სახელი";            if ($post->post_content !== $content) $changes[] = "დაარედაქტირა კონტენტი";            if ($post->post_name !== $slug) $changes[] = "შეცვალა ბმული";            if ($post->post_status !== $status) {                $tr_status = ($status == 'published') ? 'გამოქვეყნებული' : 'დრაფტი';                $changes[] = "სტატუსი: {$tr_status}";            }            $old_sidebar = (int)$post->has_sidebar;            if ($old_sidebar !== $has_sidebar) $changes[] = ($has_sidebar == 1) ? "ჩართო საიდბარი" : "გამორთო საიდბარი";            $old_img = $post->post_image;            if (empty($old_img) && !empty($image_url)) $changes[] = "დაამატა ფოტო";            elseif (!empty($old_img) && empty($image_url)) $changes[] = "წაშალა ფოტო";            elseif (!empty($old_img) && !empty($image_url) && $old_img !== $image_url) $changes[] = "შეცვალა ფოტო";            $old_template = 'default';            if (function_exists('get_post_meta')) {                $old_template = get_post_meta($post_id, '_ok_page_template', 'default');            }            if ($old_template !== $new_template) $changes[] = "შეცვალა შაბლონი";            if (!empty($changes)) {                $notif_message = "{$user_label}-მ განაახლა გვერდი '{$title}'. ცვლილებები: " . implode(", ", $changes);            } else {                $notif_message = "{$user_label}-მ განაახლა გვერდი '{$title}' (ცვლილებების გარეშე)";            }        }        // DB EXECUTION        if ($is_edit) {            $sql = "UPDATE ok_posts SET post_title=?, post_content=?, post_status=?, post_image=?, post_name=?, has_sidebar=? WHERE id=?";            $ok_db->query($sql, [$title, $content, $status, $image_url, $slug, $has_sidebar, $post_id]);            $saved_post_id = $post_id;        } else {            $sql = "INSERT INTO ok_posts (post_author, post_date, post_content, post_title, post_status, post_type, post_image, post_name, has_sidebar) VALUES (?, ?, ?, ?, ?, 'page', ?, ?, ?)";            $ok_db->query($sql, [$author, $date, $content, $title, $status, $image_url, $slug, $has_sidebar]);            $saved_post_id = $ok_db->last_insert_id();        }        if ($saved_post_id > 0) {                        // --- NOTIFICATIONS (DB + EMAIL) ---            if (!empty($notif_message)) {                                // 1. შიდა ნოთიფიკაცია (ბაზაში)                $sql_notif = "INSERT INTO ok_notifications (user_id, message, created_at, is_read) VALUES (?, ?, NOW(), 0)";                $ok_db->query($sql_notif, [$author, $notif_message]);                // 2. იმეილის გაგზავნა ადმინისტრატორზე (ახალი)                $admin_email = '';                if (function_exists('get_ok_option')) {                    $admin_email = get_ok_option('admin_email');                } else {                    $admin_email = $ok_db->get_var("SELECT option_value FROM ok_options WHERE option_name = 'admin_email'");                }                if (!empty($admin_email) && filter_var($admin_email, FILTER_VALIDATE_EMAIL)) {                    $site_title = function_exists('get_ok_option') ? get_ok_option('site_title', 'OK Engine') : 'OK Engine';                    $subject = "სისტემური შეტყობინება: " . ($is_edit ? "გვერდი განახლდა" : "ახალი გვერდი");                                        $headers = "MIME-Version: 1.0" . "\r\n";                    $headers .= "Content-type:text/html;charset=UTF-8" . "\r\n";                    $headers .= "From: " . $site_title . " <noreply@" . $_SERVER['HTTP_HOST'] . ">" . "\r\n";                    $email_content = "                    <div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee;'>                        <h3 style='color: #333;'>{$subject}</h3>                        <p><strong>საიტი:</strong> {$site_title}</p>                        <p><strong>მომხმარებელი:</strong> {$user_label}</p>                        <div style='background:#f9f9f9; padding:15px; border-left: 4px solid #0d6efd; margin: 15px 0;'>                            {$notif_message}                        </div>                        <p><small>თარიღი: " . date('Y-m-d H:i:s') . "</small></p>                        <center><a href='" . ok_get_base_url() . "/admin/index.php?page=ok-page-editor&id={$saved_post_id}' style='background:#0d6efd; color:#fff; padding:10px 20px; text-decoration:none; border-radius:5px;'>გვერდის ნახვა</a></center>                    </div>";                    mail($admin_email, $subject, $email_content, $headers);                }            }            // ----------------------------------            if (function_exists('update_post_meta')) {                update_post_meta((int)$saved_post_id, '_ok_page_template', $new_template);            }            $all_image_ids = array_unique(array_merge([$feat_img_id], $content_img_ids));            foreach ($all_image_ids as $img_id) {                if ($img_id > 0) {                    $curr_json = $ok_db->get_var("SELECT attached_post_ids FROM ok_gallery WHERE id = ?", [$img_id]);                    $attached = !empty($curr_json) ? json_decode($curr_json, true) : [];                    if (!is_array($attached)) $attached = [];                                        if (!in_array($saved_post_id, $attached)) {                        $attached[] = $saved_post_id;                        $ok_db->query("UPDATE ok_gallery SET attached_post_ids = ? WHERE id = ?", [json_encode($attached), $img_id]);                    }                }            }            $redirect_url = "index.php?page=ok-page-editor&id=" . $saved_post_id . "&success=1";            if (!headers_sent()) {                header("Location: " . $redirect_url);            } else {                echo "<script>window.location.href = '$redirect_url';</script>";            }            exit;                    } else {            echo '<div class="alert alert-danger">შეცდომა შენახვისას. მონაცემთა ბაზის შეცდომა.</div>';        }    }    // --- VIEW VARIABLES ---    $p_title   = $post ? $post->post_title : '';    $p_content = $post ? $post->post_content : '';    $p_status  = $post ? $post->post_status : 'draft';    $p_image   = $post ? ($post->post_image ?? '') : '';    $p_slug    = $post ? ($post->post_name ?? '') : '';    $site_url  = $_SERVER['HTTP_HOST'] . '/';    $p_sidebar = ($post && isset($post->has_sidebar)) ? $post->has_sidebar : 1;        $p_template = 'default';    if ($post && function_exists('get_post_meta')) {        $p_template = get_post_meta($post->id, '_ok_page_template', 'default');    }    $p_image_id = 0;    if ($p_image) {        $fname = basename($p_image);        $found = $ok_db->get_row("SELECT id FROM ok_gallery WHERE file_name = ?", [$fname]);        if($found) $p_image_id = $found->id;    }    ?>    <?php if (isset($_GET['success']) && $_GET['success'] == 1): ?>        <script>            document.addEventListener('DOMContentLoaded', function() {                Swal.fire({                    title: 'მზადაა!',                    text: 'გვერდი წარმატებით შეინახა',                    icon: 'success',                    confirmButtonText: 'კარგი',                    timer: 2000,                    timerProgressBar: true                }).then(() => {                    const url = new URL(window.location);                    url.searchParams.delete('success');                    window.history.replaceState({}, '', url);                });            });        </script>    <?php endif; ?>    <form method="post" id="main_form" action="index.php?page=ok-page-editor<?php echo $is_edit ? '&id='.$post_id : ''; ?>">        <?php if(function_exists('ok_nonce_field')) ok_nonce_field('save_page_action'); ?>        <div class="d-flex justify-content-between align-items-center mb-4">            <h1 class="h3 mb-0 fw-bold text-dark"><?php echo $is_edit ? 'გვერდის რედაქტირება' : 'ახალი გვერდი'; ?></h1>            <a href="index.php?page=ok-pages" class="btn btn-outline-secondary btn-sm px-3 rounded-pill"><i class="bi bi-arrow-left me-1"></i> უკან</a>        </div>        <div class="row g-4">            <div class="col-lg-9">                <div class="mb-3">                    <input type="text" name="post_title" id="post_title" class="form-control form-control-lg py-3 border shadow-sm fw-bold mb-2" placeholder="სათაური" value="<?php echo htmlspecialchars($p_title); ?>" required style="font-size: 1.5rem;">                                        <?php if($is_edit): ?>                    <div class="bg-light p-2 rounded border d-flex align-items-center flex-wrap gap-2 small text-muted mt-2">                        <i class="bi bi-link-45deg fs-5"></i>                        <span>ბმული:</span>                                                <div class="input-group input-group-sm flex-grow-1">                            <span class="input-group-text bg-white text-muted border-end-0"><?php echo htmlspecialchars($site_url); ?></span>                            <input type="text" name="post_name" id="post_slug_input" class="form-control border-start-0 ps-0 bg-white" value="<?php echo htmlspecialchars($p_slug); ?>">                            <button type="button" id="update_slug_btn" class="btn btn-outline-secondary px-3" title="განახლება">OK</button>                        </div>                        <a href="../<?php echo htmlspecialchars($p_slug); ?>" target="_blank" id="view_post_link" class="btn btn-sm btn-link text-decoration-none">ნახვა <i class="bi bi-box-arrow-up-right ms-1"></i></a>                    </div>                    <?php endif; ?>                </div>                                <div class="card border shadow-sm">                    <div class="card-body p-0">                        <?php                         // ID: main_page_editor                        if (function_exists('ok_render_editor')) {                            ok_render_editor('post_content', $p_content, 'main_page_editor');                        } else {                            echo '<div class="p-3 alert alert-warning">ფუნქცია ok_render_editor არ მოიძებნა.</div>';                            echo '<textarea name="post_content" class="form-control p-3" rows="15">'.htmlspecialchars($p_content).'</textarea>';                        }                        ?>                        <input type="hidden" name="content_image_ids" id="content_image_ids" value="">                    </div>                </div>            </div>            <div class="col-lg-3">                <div class="card border shadow-sm mb-4">                    <div class="card-header bg-white fw-bold py-2 small text-uppercase text-muted border-bottom">გამოქვეყნება</div>                    <div class="card-body p-3">                        <div class="mb-3">                            <label class="form-label small fw-bold text-muted">სტატუსი:</label>                            <select name="post_status" class="form-select form-select-sm">                                <option value="published" <?php echo ($p_status === 'published') ? 'selected' : ''; ?>>გამოქვეყნებული</option>                                <option value="draft" <?php echo ($p_status === 'draft') ? 'selected' : ''; ?>>დრაფტი</option>                            </select>                        </div>                                                <div class="mb-3 p-2 bg-light rounded border">                            <div class="form-check form-switch">                                <input class="form-check-input" type="checkbox" id="has_sidebar" name="has_sidebar" value="1" <?php echo ($p_sidebar == 1) ? 'checked' : ''; ?>>                                <label class="form-check-label small fw-bold text-muted" for="has_sidebar">საიდბარის ჩვენება</label>                            </div>                        </div>                        <?php                             $result = ok_get_theme_templates();                            $templates = $result['data'];                            if (!empty($templates)):                        ?>                        <div class="mb-3 bg-light p-2 rounded border">                            <label class="form-label small fw-bold text-muted mb-1">შაბლონი:</label>                            <select name="page_template" class="form-select form-select-sm">                                <option value="default">სტანდარტული</option>                                <?php foreach ($templates as $file => $name): ?>                                    <option value="<?php echo htmlspecialchars($file); ?>" <?php echo ($p_template === $file) ? 'selected' : ''; ?>>                                        <?php echo htmlspecialchars($name); ?>                                    </option>                                <?php endforeach; ?>                            </select>                        </div>                        <?php endif; ?>                        <?php if(!$is_edit): ?>                        <div class="mb-3">                            <label class="form-label small fw-bold text-muted">ბმული (Slug):</label>                            <input type="text" name="post_name" class="form-control form-control-sm" value="<?php echo htmlspecialchars($p_slug); ?>">                        </div>                        <?php endif; ?>                        <div class="d-grid">                            <button type="submit" name="save_page" class="btn btn-primary btn-sm">                                <i class="bi bi-save me-1"></i> <?php echo $is_edit ? 'განახლება' : 'გამოქვეყნება'; ?>                            </button>                        </div>                    </div>                </div>                <div class="card border shadow-sm mb-4">                    <div class="card-header bg-white fw-bold py-2 small text-uppercase text-muted border-bottom">მთავარი სურათი</div>                    <div class="card-body p-3 text-center">                        <div id="image-preview-container" class="mb-3 border rounded overflow-hidden bg-light position-relative <?php echo empty($p_image) ? 'd-none' : ''; ?>">                            <img id="image-preview" src="<?php echo htmlspecialchars($p_image); ?>" class="img-fluid" style="max-height: 150px; width: 100%; object-fit: cover;">                            <button type="button" id="remove-image-btn" class="btn btn-sm btn-danger position-absolute top-0 end-0 m-1 shadow-sm"><i class="bi bi-x-lg"></i></button>                        </div>                        <input type="hidden" name="post_image_url" id="post_image_url" value="<?php echo htmlspecialchars($p_image); ?>">                        <input type="hidden" name="post_image_id" id="post_image_id" value="<?php echo $p_image_id; ?>">                        <div class="d-grid">                            <button type="button" onclick="openGalleryForFeatured()" class="btn btn-outline-primary btn-sm">                                <i class="bi bi-images me-1"></i> აირჩიეთ ფოტო                            </button>                        </div>                    </div>                </div>            </div>        </div>    </form>    <script>    document.addEventListener('DOMContentLoaded', () => {        // Slug AJAX განახლება        const btn = document.getElementById('update_slug_btn');        if (btn) { btn.addEventListener('click', function() {             const slugInput = document.getElementById('post_slug_input');             const titleInput = document.getElementById('post_title');             const viewLink = document.getElementById('view_post_link');             const originalText = btn.innerText;             btn.innerText = '...'; btn.disabled = true;             const formData = new FormData();             formData.append('ajax_action', 'update_slug');             formData.append('post_id', '<?php echo $post_id; ?>');             formData.append('slug', slugInput.value);             formData.append('title', titleInput.value);             fetch(window.location.href, { method: 'POST', body: formData }).then(response => response.json()).then(data => { if (data.success) { slugInput.value = data.new_slug; if (viewLink) viewLink.href = '../' + data.new_slug; btn.innerHTML = '<i class="bi bi-check"></i>'; setTimeout(() => { btn.innerText = originalText; btn.disabled = false; }, 1500); } }); }); }                // გალერეის მოდალი        function openGalleryModal(onSelectCallback) { Swal.fire({ title: 'აირჩიეთ სურათი', width: '800px', html: `<div class="d-flex justify-content-end mb-2"><label class="btn btn-sm btn-success" for="quick-upload"><i class="bi bi-cloud-upload me-1"></i> ახალი ფოტო</label><input type="file" id="quick-upload" style="display:none;" accept="image/*" multiple></div><div id="swal-gallery-grid" class="d-flex flex-wrap gap-2 justify-content-center p-2" style="max-height: 400px; overflow-y: auto;"><i>იტვირთება...</i></div>`, showCancelButton: true, showConfirmButton: false, cancelButtonText: 'დახურვა', didOpen: () => { loadImages(onSelectCallback); document.getElementById('quick-upload').addEventListener('change', function() { if(this.files.length > 0) { const formData = new FormData(); for(let i=0; i<this.files.length; i++) formData.append('gallery_image[]', this.files[i]); fetch('index.php?page=ok-gallery&action=upload_images_ajax', { method: 'POST', body: formData }).then(r => r.json()).then(res => { if(res.success) { loadImages(onSelectCallback); } }); } }); } }); }                function loadImages(onSelectCallback) { fetch('index.php?page=ok-gallery&action=get_images_ajax').then(r => r.json()).then(res => { const grid = document.getElementById('swal-gallery-grid'); if(res.success && res.images.length > 0) { grid.innerHTML = ''; res.images.forEach(img => { const div = document.createElement('div'); div.style.cssText = 'width: 120px; height: 120px; cursor: pointer; border: 2px solid #eee; overflow: hidden; border-radius: 4px;'; div.innerHTML = `<img src="${img.url}" style="width: 100%; height: 100%; object-fit: cover;">`; div.addEventListener('click', () => { onSelectCallback(img); Swal.close(); }); grid.appendChild(div); }); } else { grid.innerHTML = '<p class="text-muted">გალერეა ცარიელია.</p>'; } }); }                // 1. მთავარი სურათი        window.openGalleryForFeatured = function() { openGalleryModal((img) => { document.getElementById('post_image_url').value = img.url; document.getElementById('post_image_id').value = img.id; document.getElementById('image-preview').src = img.url; document.getElementById('image-preview-container').classList.remove('d-none'); }); };                // 2. ახალი ედიტორის ინტეგრაცია (Pages)        window.openGalleryForEditor = function(editorId) {             const targetId = editorId || 'main_page_editor';            openGalleryModal((img) => {                 if(window.okInsertImage) {                    window.okInsertImage(targetId, img.url);                } else {                    console.error('okInsertImage function missing.');                }                const hiddenInput = document.getElementById('content_image_ids');                 let currentIds = hiddenInput.value ? hiddenInput.value.split(',') : [];                 if (!currentIds.includes(img.id.toString())) {                     currentIds.push(img.id);                     hiddenInput.value = currentIds.join(',');                 }             });         };                const removeBtn = document.getElementById('remove-image-btn'); if(removeBtn) { removeBtn.addEventListener('click', () => { document.getElementById('post_image_url').value = ''; document.getElementById('post_image_id').value = '0'; document.getElementById('image-preview').src = ''; document.getElementById('image-preview-container').classList.add('d-none'); }); }    });    </script>    <?php}?>